parts.text:
[
  {
    "statement": "Several methods can support bee-friendly habitats on farmland.",
    "citations": []
  },
  {
    "statement": "Planting dedicated floral resources has been shown to be effective for supporting bee habitats.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Substantial numbers of wild bees have been recorded foraging on both perennial and annual sown flowering plants in Europe and North America.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Patches of phacelia attracted a high number of wild bees, particularly bumblebees.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Planted perennial leguminous herbs, such as clovers, were more attractive to bumblebees in landscapes with more arable farming.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Providing artificial nest sites is an effective measure for supporting bee-friendly habitats.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Nest boxes for solitary bees showed occupancy in the vast majority of replicated trials.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Artificial nest sites, including cut hollow stems, tubes, and drilled wood blocks, are used by many species of solitary bees.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "The number of occupied solitary bee nests could double over three years with the repeated provision of nest boxes.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Other strategies for creating bee-friendly habitats have shown mixed or specific results.",
    "citations": []
  },
  {
    "statement": "Providing set-aside areas that are annually mown and left to naturally regenerate for two or more years can lead to higher species richness of nesting and foraging bees.",
    "citations": [
      "7"
    ]
  },
  {
    "statement": "Reducing the intensity of farmland meadow management resulted in enhanced numbers and diversity of wild bees in some trials.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "Methods to reduce farmland meadow management intensity include delaying the first cut and using fewer agrochemicals.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "Agri-environment schemes have shown varied outcomes for bee populations.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Some trials of agri-environment schemes in Europe found enhanced bee diversity or abundance, while other trials found no enhancement.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "No evidence was found to support the effectiveness of introducing nest boxes already stocked with solitary bees.",
    "citations": [
      "81"
    ]
  },
  {
    "statement": "No evidence was found to support the effectiveness of increasing the use of clover leys on farmland.",
    "citations": [
      "16"
    ]
  }
]

[
  {
    "statement": "There is no evidence of the effects on wild bee communities of connecting patches of natural or semi-natural habitat.",
    "citations": [
      "10"
    ]
  }
]

[
  {
    "statement": "There is no evidence on the impact of retaining dead wood in forests or woodlands on wild bee communities or populations.",
    "citations": [
      "36"
    ]
  },
  {
    "statement": "'No evidence' means that no studies were found that directly and quantitatively tested the action of retaining dead wood in forests.",
    "citations": [
      "36"
    ]
  },
  {
    "statement": "It is not possible to assess whether the action of retaining dead wood in forests is effective or has any harmful impacts.",
    "citations": [
      "36"
    ]
  }
]

[
  {
    "statement": "There is no evidence for the effects of reintroducing bumblebee queens.",
    "citations": [
      "51"
    ]
  },
  {
    "statement": "The term 'no evidence' for an action means that no studies have yet been found that directly and quantitatively tested that action during systematic journal and report searches.",
    "citations": [
      "51"
    ]
  },
  {
    "statement": "It has been impossible to assess whether or not the action of reintroducing bumblebee queens is effective or has any harmful impacts.",
    "citations": [
      "51"
    ]
  }
]

[
  {
    "statement": "Trials in Europe and North America found significant numbers of wild bees foraging on sown perennial and annual flowering plants in agricultural settings.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "In ten trials that monitored bees on farmland, patches were sown with a high proportion of phacelia.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "All but one of these trials found substantial numbers of foraging wild (non-Apis) bees, particularly bumblebees.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "A replicated controlled trial in the UK showed that planted perennial leguminous herbs, including clovers, were more attractive to bumblebees in landscapes with a greater proportion of arable farming.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "A trial in Canada demonstrated that planting bigleaf lupine in apple orchards resulted in a significant enhancement of reproductive success for blue orchard mason bees.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "One trial in the Netherlands indicated that bee numbers and species richness do not increase in farmland 50 to 1,500 meters away from planted flower patches.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Two trials in Germany found no or relatively few species of solitary bee nesting on set-aside fields sown with phacelia or clover.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "There is no evidence that increasing the use of clover leys enhances wild bee populations.",
    "citations": [
      "16"
    ]
  },
  {
    "statement": "No evidence has been captured for the effects on farmland wildlife of introducing nest boxes stocked with solitary bees.",
    "citations": [
      "81"
    ]
  }
]

[
  {
    "statement": "No evidence was found concerning the effects on wild bee communities of connecting patches of natural or semi-natural habitat.",
    "citations": [
      "10"
    ]
  },
  {
    "statement": "The term 'no evidence' means that no studies that directly and quantitatively tested the connecting of natural or semi-natural habitat have been found.",
    "citations": [
      "10"
    ]
  },
  {
    "statement": "It is not possible to assess whether the action of connecting patches of natural or semi-natural habitat is effective.",
    "citations": [
      "10"
    ]
  },
  {
    "statement": "It is not possible to assess whether the action of connecting patches of natural or semi-natural habitat has any harmful impacts.",
    "citations": [
      "10"
    ]
  }
]

[
  {
    "statement": "No evidence was found to suggest a specific impact of climate change on the nesting success of ground-nesting bees in the UK.",
    "citations": [
      "13",
      "47",
      "80",
      "81"
    ]
  }
]

[
  {
    "statement": "Three replicated trials showed that a mix of agricultural forage plants including legumes attracts greater numbers of bumblebees than a perennial wildflower mix, at least in the first year.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "One small replicated trial showed that common long-tongued bumblebee species strongly preferred plots of perennial wildflower seed mix over a mix of annual forage plants.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Three trials in the UK found evidence that margins sown with agricultural legume plants degrade in their value to bumblebees.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Margins sown with agricultural legume plants would need to be re-sown every few years.",
    "citations": [
      "18"
    ]
  }
]
